def transform(grid):
    """Extend a full 2-line past the object on its occupied side with an 8-line."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    # Find a complete straight 2-line.
    vertical = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    horizontal = [r for r in range(h) if all(v == 2 for v in grid[r])]
    if vertical:
        c = vertical[0]
        side = 1 if any(grid[r][j] != bg and grid[r][j] != 2 for r in range(h) for j in range(c+1,w)) else -1
        cells = [(r,j) for r in range(h) for j in range(w) if grid[r][j] != bg and grid[r][j] != 2]
        if cells:
            edge = max(j for r,j in cells) if side == 1 else min(j for r,j in cells)
            target = edge + side
            if 0 <= target < w:
                for r in range(h):
                    if grid[r][target] == bg:
                        out[r][target] = 8
    elif horizontal:
        r = horizontal[0]
        side = 1 if any(grid[i][j] != bg and grid[i][j] != 2 for i in range(r+1,h) for j in range(w)) else -1
        cells = [(i,j) for i in range(h) for j in range(w) if grid[i][j] != bg and grid[i][j] != 2]
        if cells:
            edge = max(i for i,j in cells) if side == 1 else min(i for i,j in cells)
            target = edge + side
            if 0 <= target < h:
                for j in range(w):
                    if grid[target][j] == bg:
                        out[target][j] = 8
    return out
